#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

int64 digitSum(int64 x) {
    int64 sum = 0;
    while (x > 0) {
        sum += x % 10;
        x /= 10;
    }
    return sum;
}

int64 integerSqrt(i128 value) {
    int64 low = 0, high = 7000000000LL;
    while (low <= high) {
        int64 mid = low + (high - low) / 2;
        i128 square = (i128)mid * mid;
        if (square <= value)
            low = mid + 1;
        else
            high = mid - 1;
    }
    return high;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n;
    cin >> n;

    int64 answer = LLONG_MAX;

    for (int64 sum = 1; sum <= 171; ++sum) {
        i128 discriminant = (i128)sum * sum + (i128)4 * n;
        int64 root = integerSqrt(discriminant);

        if ((i128)root * root != discriminant || root < sum ||
            (root - sum) % 2 != 0) {
            continue;
        }

        int64 x = (root - sum) / 2;
        if (x > 0 && digitSum(x) == sum &&
            (i128)x * (x + sum) == n) {
            answer = min(answer, x);
        }
    }

    cout << (answer == LLONG_MAX ? -1 : answer) << '\n';
    return 0;
}

