    int64 root = sqrtl(static_cast<long double>(n));
    while (i128(root + 1) * (root + 1) <= n) ++root;
    while (i128(root) * root > n) --root;

    int64 maxDigitSum = 9LL * to_string(n).size();
    int64 low = max<int64>(1, root - maxDigitSum - 1);

    for (int64 x = low; x <= root; ++x) {
        if (i128(x) * (x + digitSum(x)) == n) {
            cout << x << '\n';
            return 0;
        }
    }

    cout << -1 << '\n';
    return 0;
}

